import{_ as i,C as p,o as a,c as u,a2 as r,b as n,w as o,a as s,E,a3 as l}from"./chunks/framework.BC3NdntU.js";const m=JSON.parse('{"title":"2.6 V8 引擎与内存(GC 与泄漏排查)","description":"","frontmatter":{},"headers":[],"relativePath":"卷二-浏览器工作原理/2.6-V8引擎与内存.md","filePath":"卷二-浏览器工作原理/2.6-V8引擎与内存.md","lastUpdated":1788793134000}'),d={name:"卷二-浏览器工作原理/2.6-V8引擎与内存.md"};function A(g,t,c,C,h,B){const e=p("Mermaid");return a(),u("div",null,[t[2]||(t[2]=r('<h1 id="_2-6-v8-引擎与内存-gc-与泄漏排查" tabindex="-1">2.6 V8 引擎与内存(GC 与泄漏排查) <a class="header-anchor" href="#_2-6-v8-引擎与内存-gc-与泄漏排查" aria-label="Permalink to &quot;2.6 V8 引擎与内存(GC 与泄漏排查)&quot;">​</a></h1><blockquote><p>卷:卷二 · 浏览器工作原理 难度:⭐⭐⭐ 专家 | 阅读时间:35min | 状态:深度增强</p></blockquote><hr><h2 id="引言-js-到底怎么跑-内存怎么收" tabindex="-1">引言:JS 到底怎么跑,内存怎么收 <a class="header-anchor" href="#引言-js-到底怎么跑-内存怎么收" aria-label="Permalink to &quot;引言:JS 到底怎么跑,内存怎么收&quot;">​</a></h2><p>V8 是 Chrome 与 Node 共用的 JS 引擎。深挖要懂<strong>多层编译流水线</strong>与<strong>三色标记 GC</strong>,才能解释性能现象、并在内存蹭蹭涨时知道去哪查。</p><hr><h2 id="一、v8-编译流水线-现代分层-一图" tabindex="-1">一、V8 编译流水线(现代分层,一图) <a class="header-anchor" href="#一、v8-编译流水线-现代分层-一图" aria-label="Permalink to &quot;一、V8 编译流水线(现代分层,一图)&quot;">​</a></h2>',7)),(a(),n(l,null,{default:o(()=>[E(e,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%BA%90%E7%A0%81%5D%20--%3E%7CParser%7C%20B%5BAST%5D%0A%20%20%20%20B%20--%3E%20C%5BIgnition%20%E8%A7%A3%E9%87%8A%E5%99%A8%3Cbr%2F%3E%E5%AD%97%E8%8A%82%E7%A0%81%2C%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8%5D%0A%20%20%20%20C%20--%3E%20D%5BSparkplug%20%E5%BF%AB%E9%80%9F%E7%BC%96%E8%AF%91%E5%99%A8%3Cbr%2F%3E%E9%9D%9E%E4%BC%98%E5%8C%96%E6%9C%BA%E5%99%A8%E7%A0%81%2C%E6%8F%90%E9%80%9F%5D%0A%20%20%20%20C%20--%3E%7C%E5%87%BD%E6%95%B0%E5%8F%98%E7%83%AD%7C%20E%5BMaglev%20%E4%B8%AD%E9%97%B4%E7%BC%96%E8%AF%91%E5%99%A8%3Cbr%2F%3E%E5%BF%AB%E9%80%9F%E4%BC%98%E5%8C%96%5D%0A%20%20%20%20E%20--%3E%7C%E6%9B%B4%E7%83%AD%20%2B%20%E7%B1%BB%E5%9E%8B%E7%A8%B3%E5%AE%9A%7C%20F%5BTurboFan%20%E4%BC%98%E5%8C%96%E7%BC%96%E8%AF%91%E5%99%A8%3Cbr%2F%3E%E9%AB%98%E5%BA%A6%E4%BC%98%E5%8C%96%E6%9C%BA%E5%99%A8%E7%A0%81%5D%0A%20%20%20%20F%20--%3E%7C%E5%81%87%E8%AE%BE%E5%A4%B1%E6%95%88%7C%20G%5B%E5%8F%8D%E4%BC%98%E5%8C%96%20Deopt%3Cbr%2F%3E%E5%9B%9E%E9%80%80%E5%88%B0%20Sparkplug%2F%E5%AD%97%E8%8A%82%E7%A0%81%5D%0A%20%20%20%20G%20--%3E%20C%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=r('<p><strong>为什么分层编译?</strong> 这是&quot;<strong>启动快 vs 长期快</strong>&quot;的权衡:</p><ul><li>先用<strong>解释器</strong>(Ignition)零等待启动</li><li>再上<strong>快速编译器</strong>(Sparkplug)把非热点代码也提点速(不追求极致)</li><li>只有<strong>真热点 + 类型稳定</strong>才上 TurboFan 深度优化</li><li>假设失效就<strong>反优化</strong>回退,避免&quot;优化错&quot;的代价</li></ul><blockquote><p>反优化的根源:<strong>JS 是动态类型</strong>。TurboFan 基于&quot;这个对象的形状稳定&quot;做内联缓存优化,一旦类型变了(反复增删属性),假设失效 → 反优化 → 变慢。所以&quot;对象形状稳定&quot;是 V8 性能的铁律(呼应 1.1)。</p></blockquote><hr><h2 id="二、内存-栈与堆" tabindex="-1">二、内存:栈与堆 <a class="header-anchor" href="#二、内存-栈与堆" aria-label="Permalink to &quot;二、内存:栈与堆&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>存什么</th><th>特点</th></tr></thead><tbody><tr><td>栈</td><td>原始值、调用帧、引用</td><td>小而快,自动释放</td></tr><tr><td>堆</td><td>对象、数组、闭包环境</td><td>大而慢,GC 管理</td></tr></tbody></table><hr><h2 id="三、分代-三色标记-gc-核心" tabindex="-1">三、分代 + 三色标记 GC(核心) <a class="header-anchor" href="#三、分代-三色标记-gc-核心" aria-label="Permalink to &quot;三、分代 + 三色标记 GC(核心)&quot;">​</a></h2>',8)),(a(),n(l,null,{default:o(()=>[E(e,{id:"mermaid-97",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E6%96%B0%E7%94%9F%E4%BB%A3%20Young%5D%20--%3E%7CScavenger%20%E5%8D%8A%E7%A9%BA%E9%97%B4%E5%A4%8D%E5%88%B6%3Cbr%2F%3E%E5%B9%B8%E5%AD%98%E5%A4%9A%E6%AC%A1%E6%99%8B%E5%8D%87%7C%20C%5B%E8%80%81%E7%94%9F%E4%BB%A3%20Old%5D%0A%20%20%20%20C%20--%3E%7C%E6%A0%87%E8%AE%B0-%E6%B8%85%E9%99%A4%20Mark-Sweep%7C%20D%5B%E6%B8%85%E6%AD%BB%E5%AF%B9%E8%B1%A1%5D%0A%20%20%20%20C%20--%3E%7C%E7%A2%8E%E7%89%87%E5%A4%9A%20%E6%A0%87%E8%AE%B0-%E6%95%B4%E7%90%86%20Compact%7C%20E%5B%E5%8E%8B%E7%BC%A9%5D%0A%20%20%20%20C%20-.-%3E%7C%E5%A2%9E%E9%87%8F%2F%E5%B9%B6%E5%8F%91%E6%A0%87%E8%AE%B0%7C%20F%5B%E5%87%8F%E5%B0%8F%E5%81%9C%E9%A1%BF%20stop-the-world%5D%0A"})]),fallback:o(()=>[...t[1]||(t[1]=[s(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=r(`<h3 id="_1-新生代-scavenger-半空间复制" tabindex="-1">1. 新生代:Scavenger(半空间复制) <a class="header-anchor" href="#_1-新生代-scavenger-半空间复制" aria-label="Permalink to &quot;1. 新生代:Scavenger(半空间复制)&quot;">​</a></h3><ul><li>新生代分&quot;From-Space / To-Space&quot;两半</li><li>GC 时把<strong>活对象复制到 To</strong>,清空 From,交换两半</li><li>快,但每轮只处理少量&quot;大多已死&quot;的对象</li></ul><h3 id="_2-老生代-mark-sweep-mark-compact" tabindex="-1">2. 老生代:Mark-Sweep + Mark-Compact <a class="header-anchor" href="#_2-老生代-mark-sweep-mark-compact" aria-label="Permalink to &quot;2. 老生代:Mark-Sweep + Mark-Compact&quot;">​</a></h3><ul><li><strong>三色标记法</strong>:白(未访)/灰(已访未扫子)/黑(已扫完)迭代标记活对象</li><li>标记完,<strong>清除</strong>白色(死)对象;碎片多了再<strong>整理(compact)</strong></li><li><strong>增量/并发标记</strong>:把标记切成小片、穿插执行,或放到后台线程,减小&quot;全停顿&quot;</li></ul><p><strong>为什么分代?</strong> 对象&quot;朝生暮死&quot;是常态(大多数对象很快没用),所以新生代用&quot;快但只处理小区域&quot;的复制法,老生代用&quot;全面但更重&quot;的标记清除。按生命周期分而治之,比一刀切高效。</p><hr><h2 id="四、内存泄漏-识别与排查" tabindex="-1">四、内存泄漏:识别与排查 <a class="header-anchor" href="#四、内存泄漏-识别与排查" aria-label="Permalink to &quot;四、内存泄漏:识别与排查&quot;">​</a></h2><p><strong>常见泄漏源</strong>:全局变量 / 闭包长持大对象 / 未清理定时器监听器 / 游离 DOM 引用 / Map 无限增长。</p><p><strong>排查(DevTools):</strong></p><ol><li><strong>Performance</strong>:堆曲线&quot;锯齿不回落&quot;= 疑似泄漏</li><li><strong>Memory → Heap Snapshot</strong>:前后快照对比 Delta</li><li><strong>Allocation instrumentation</strong>:看谁在持续分配</li></ol><blockquote><p>三板斧:<code>定时器/监听器清理了没</code>、<code>闭包有没有长持大对象</code>、<code>缓存有没有上限</code>。</p></blockquote><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>V8:源码→AST→Ignition(字节码)→Sparkplug(快)→Maglev→TurboFan(热) ;类型不稳→反优化</span></span>
<span class="line"><span>GC:分代——新生代(Scavenger 半空间复制)→老生代(Mark-Sweep/Compact,三色标记,增量并发减停顿)</span></span>
<span class="line"><span>泄漏三源:全局/闭包/未清理定时器监听器 → Memory 快照对比排查</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="六、面试题" tabindex="-1">六、面试题 <a class="header-anchor" href="#六、面试题" aria-label="Permalink to &quot;六、面试题&quot;">​</a></h2><p><strong>Q1:什么是 JIT?V8 为什么不用纯解释或纯编译?</strong></p><p>JIT 先用解释器<strong>快速启动</strong>,运行时识别<strong>热点</strong>编译成机器码<strong>加速</strong>,假设失效反优化兜底。兼顾&quot;启动快 + 长期快&quot;。</p><p><strong>Q2:什么是&quot;反优化(Deoptimization)&quot;?什么触发?</strong></p><p>TurboFan 基于&quot;对象形状稳定/类型稳定&quot;做优化;一旦假设失效(反复增删属性、类型改变),就<strong>回退到未优化代码</strong>,叫反优化,代价是性能骤降。触发是&quot;对象形状不稳定&quot;。</p><p><strong>Q3:解释三色标记法(GC)</strong></p><p>GC 标记阶段用&quot;白/灰/黑&quot;标记对象:白=未访问,灰=已访问但其子对象未扫,黑=已访问且子对象扫完。从根出发迭代,最终白色对象就是&quot;不可达的死对象&quot;,被清除。</p><p><strong>Q4:为什么推荐 WeakMap 做缓存而非 Map?</strong></p><p><code>Map</code> 键强引用,只要 Map 活着键对象就不回收 → 无限增长泄漏;<code>WeakMap</code> 键弱引用,键对象无引用即被 GC,缓存自动失效不堆积。</p><p><strong>Q5:泄漏和&quot;内存占用高&quot;是一回事吗?</strong></p><p>不是。占用高可能是合理大数据;泄漏是&quot;本该回收却持续增长不回落&quot;。判断靠观测:堆曲线只涨不落、快照对比对象数量异常增长。</p><p><strong>Q6:如何用 Chrome DevTools 定位一处内存泄漏?</strong></p><p>① Performance 录制,看堆曲线是否&quot;锯齿不回落&quot;;② Heap Snapshot 在嫌疑操作前后各拍一次,对比 <strong>Delta</strong> 找异常增长的对象与引用链;③ Allocation instrumentation 定位持续分配的调用栈。</p><hr><p>📎 参考:V8 官方博客、Chrome DevTools《Memory》、MDN《内存管理》、GC 三色标记相关论文</p>`,30))])}const b=i(d,[["render",A]]);export{m as __pageData,b as default};
